import{_ as i,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"MAAS as a Backend- Provisioning Infrastructure for Teuthology Suites With Vaibhav Mahajan","description":"","frontmatter":{"title":"MAAS as a Backend- Provisioning Infrastructure for Teuthology Suites With Vaibhav Mahajan","date":"2026-04-22T00:00:00.000Z","updated":"2026-04-23T00:00:00.000Z","tags":["MAAS","Teuthology","裸金属provisioning","Ceph测试框架","自动化运维"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/MAAS_as_a_Backend_-_Provisioning_Infrastructure_for_Teuthology_Suites_With_Vaibhav_Mahajan.md","filePath":"posts/2026/MAAS_as_a_Backend_-_Provisioning_Infrastructure_for_Teuthology_Suites_With_Vaibhav_Mahajan.md","lastUpdated":1780459816000}'),e={name:"posts/2026/MAAS_as_a_Backend_-_Provisioning_Infrastructure_for_Teuthology_Suites_With_Vaibhav_Mahajan.md"};function s(n,a,r,h,d,p){return t(),l("div",null,[...a[0]||(a[0]=[o(`<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由来自 IBM India 的 DevOps 工程师 Vaibhav Mahajan 主讲，介绍了为 Teuthology（Ceph 的集成测试框架）新增的 MAAS（Metal as a Service）裸金属 provisioning 后端支持。演讲涵盖了架构设计、节点生命周期管理、配置要求以及实际演示。</p><h2 id="背景-为什么选择-maas" tabindex="-1">背景：为什么选择 MAAS <a class="header-anchor" href="#背景-为什么选择-maas" aria-label="Permalink to &quot;背景：为什么选择 MAAS&quot;">​</a></h2><p>Teuthology 目前支持三种 provisioning 平台：</p><ul><li><strong>Fog</strong>：专用于裸金属的镜像与 provisioning 工具，需要预先配置</li><li><strong>OpenStack</strong>：虚拟化平台，支持部署 VM 并执行测试</li><li><strong>MAAS（新增）</strong>：提供类云体验的裸金属管理工具</li></ul><p>选择 MAAS 的主要原因：</p><ol><li><strong>丰富的 REST API</strong>：MAAS 提供的 API 集合与 Teuthology 现有的 Fog 集成模式高度契合，支持机器的创建、删除等标准操作</li><li><strong>Cloud-init 支持</strong>：可像云平台一样通过 cloud-init 文件完成节点初始化配置</li><li><strong>动态服务管理</strong>：支持根据用户请求动态进行服务定位和服务器分配，提供真正的类云体验</li></ol><h2 id="系统架构与节点生命周期" tabindex="-1">系统架构与节点生命周期 <a class="header-anchor" href="#系统架构与节点生命周期" aria-label="Permalink to &quot;系统架构与节点生命周期&quot;">​</a></h2><h3 id="整体工作流" tabindex="-1">整体工作流 <a class="header-anchor" href="#整体工作流" aria-label="Permalink to &quot;整体工作流&quot;">​</a></h3><p>Teuthology 负责主要的 inventory 管理，完整的节点生命周期如下：</p><ol><li><strong>节点选择</strong>：Teuthology 根据 suite 中指定的机器类型，或用户显式请求的特定机器名称，向 Padles（后端数据库）发送分配请求</li><li><strong>Provisioning</strong>：请求推送至 MAAS 后，MAAS 负责处理 PXE 启动、OS 部署以及 cloud-init 配置</li><li><strong>测试执行</strong>：Provisioning 完成后，Teuthology 通过 SSH 连接到机器，执行部署步骤和测试用例</li><li><strong>清理回收</strong>：测试完成后，Teuthology 向 MAAS 发送删除请求，将机器恢复至 ready 状态</li></ol><p><strong>重要约定</strong>：Teuthology 中的机器名称必须与 MAAS 中的机器名称保持一致，需在配置 Padles 或 Pulpito 时统一管理。</p><h2 id="部署要求" tabindex="-1">部署要求 <a class="header-anchor" href="#部署要求" aria-label="Permalink to &quot;部署要求&quot;">​</a></h2><h3 id="maas-侧要求" tabindex="-1">MAAS 侧要求 <a class="header-anchor" href="#maas-侧要求" aria-label="Permalink to &quot;MAAS 侧要求&quot;">​</a></h3><ul><li>已部署 MAAS controller，并完成机架（rack）配置</li><li>待管理的机器已添加至 MAAS 并处于 <strong>ready 状态</strong>（即空闲理想状态）</li><li>网络配置正确，Teuthology 控制节点可访问 MAAS 管理的子网</li><li>机器已完成 commissioning</li><li>已生成 API key（包含 consumer key、consumer token 和 secret）</li></ul><h3 id="teuthology-控制节点要求" tabindex="-1">Teuthology 控制节点要求 <a class="header-anchor" href="#teuthology-控制节点要求" aria-label="Permalink to &quot;Teuthology 控制节点要求&quot;">​</a></h3><ul><li>运行 dispatcher 和 supervisor 进程</li><li>控制节点的 SSH 公钥需添加至 MAAS，以便 MAAS 在部署机器时将其注入为 authorized key</li><li>配置 Python 虚拟环境（与 Fog 后端要求相同）</li></ul><h3 id="teuthology-yaml-配置" tabindex="-1">teuthology.yaml 配置 <a class="header-anchor" href="#teuthology-yaml-配置" aria-label="Permalink to &quot;teuthology.yaml 配置&quot;">​</a></h3><p>需在配置文件中新增以下字段：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  api_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http:/&lt;maas-server&gt;:5240/MAAS/api/2.0/</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  api_key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;consumerkey&gt;:&lt;consumer_token&gt;:&lt;secret&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  machine_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;类型标签&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;超时时间（秒）&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  user_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    # cloud-init 配置</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    # 可配置用户、软件源等初始化内容</span></span></code></pre></div><h2 id="核心操作详解" tabindex="-1">核心操作详解 <a class="header-anchor" href="#核心操作详解" aria-label="Permalink to &quot;核心操作详解&quot;">​</a></h2><h3 id="lock-锁定-操作" tabindex="-1">Lock（锁定）操作 <a class="header-anchor" href="#lock-锁定-操作" aria-label="Permalink to &quot;Lock（锁定）操作&quot;">​</a></h3><p>锁定操作存在双重锁定机制：</p><ul><li><strong>Teuthology 侧锁定</strong>：防止其他用户访问或操作该机器</li><li><strong>MAAS 侧锁定</strong>：防止对机器执行删除或更新等操作</li></ul><p>操作流程：</p><ol><li>Teuthology 向Paddles 查询可用机器</li><li>Paddles 分配机器并通知 supervisor</li><li>Teuthology 向 MAAS 发起REST API 部署请求</li></ol><p>存在两种场景：</p><ul><li><strong>场景一</strong>：机器处于 ready 或 new 状态 → 移至 allocated 状态 → 按指定 OS 类型和版本部署 → 锁定</li><li><strong>场景二</strong>：机器已处于 deployed 状态但在 Teuthology 中显示为未锁定 → 先解锁并释放 → 回到 allocated 状态 → 重新部署 → 锁定</li></ul><p>如需覆盖锁定，可使用 Teuthology 的 <code>owner</code> 标签进行匹配。</p><h3 id="unlock-解锁-操作" tabindex="-1">Unlock（解锁）操作 <a class="header-anchor" href="#unlock-解锁-操作" aria-label="Permalink to &quot;Unlock（解锁）操作&quot;">​</a></h3><ol><li>Teuthology 验证 Paddles 中的 inventory owner与请求发送者匹配</li><li>向 MAAS 发送 release 请求</li></ol><p>三种处理情形：</p><ul><li>机器已处于 ready 或 allocated 状态（因状态不一致）→ 仅在 Teuthology 中标记为已释放，不做其他操作</li><li>机器处于 deploying 状态 → 中止部署，恢复至 ready 状态</li><li>机器处于 deployed 状态 → 释放并解锁，回归资源池</li></ul><h3 id="suite-执行流程" tabindex="-1">Suite 执行流程 <a class="header-anchor" href="#suite-执行流程" aria-label="Permalink to &quot;Suite 执行流程&quot;">​</a></h3><ol><li>Dispatcher 获取所需测试 suite 列表</li><li>将任务调度至 BeanStalkd 队列</li><li>Supervisor 读取任务，根据机器类型从资源池选取节点</li><li>执行与 lock 操作相同的 MAAS 交互序列</li><li>测试完成后，Teuthology 删除机器并将其恢复至 ready 状态</li></ol><h2 id="监控与故障排查" tabindex="-1">监控与故障排查 <a class="header-anchor" href="#监控与故障排查" aria-label="Permalink to &quot;监控与故障排查&quot;">​</a></h2><p>两套系统协同工作，提供完整的可观测性：</p><table tabindex="0"><thead><tr><th>系统</th><th>用途</th></tr></thead><tbody><tr><td><strong>MAAS Dashboard</strong></td><td>查看机器部署和清理的详细步骤日志</td></tr><tr><td><strong>Pulpito Dashboard</strong></td><td>监控 Teuthology 的执行、锁定等操作日志</td></tr><tr><td><strong>Supervisor 日志</strong>（控制节点）</td><td>获取最详细的操作日志，也可通过 Pulpito 访问</td></tr></tbody></table><p>PXE 启动等底层问题需直接依赖 MAAS 日志进行排查。</p><h2 id="演示环节" tabindex="-1">演示环节 <a class="header-anchor" href="#演示环节" aria-label="Permalink to &quot;演示环节&quot;">​</a></h2><p>演讲者使用 LXD（Linux Containers）环境进行了演示，展示了 MAAS 管理虚拟机的能力（MAAS 同样支持真实裸金属）：</p><ul><li>搭建了一台 LXD 宿主机，添加了多台不同配置的 VM（如 burndup、prana 等），统一归类为 <code>lxd</code> 机器类型</li><li>在 Pulpito 中可见这些机器以 <code>lxd</code> 类型注册，部分处于 ready 状态，部分处于 deployed 状态</li><li>演示了单机锁定（<code>lock</code> 命令）、单机解锁（<code>unlock</code> 命令）以及多机批量锁定（\`lock many）操作</li><li>演示了完整的 smoke test suite 执行流程，包括 dispatcher 调度和 supervisor 节点选择</li></ul><p>LXD 机器的 commissioning 流程：在 MAAS 中创建机器后，需配置 power 类型为 LXD，提供宿主机地址、实例名称和证书，完成 commissioning 后机器进入 allocated 状态，分配给用户后变为 ready 状态。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>MAAS 作为 Teuthology 的新 provisioning 后端，配置简单，只需：</p><ol><li>在 <code>teuthology.yaml</code> 中添加 MAAS 相关配置</li><li>将 Teuthology 控制节点的 SSH 公钥添加至 MAAS</li></ol><p>在网络配置正确的前提下，即可实现与 Fog 后端同等的裸金属自动化测试能力，同时获得更好的类云管理体验和更丰富的 API 支持。</p>`,47)])])}const c=i(e,[["render",s]]);export{g as __pageData,c as default};
